/// <reference lib="webworker" />

// This benchmark intentionally imports the generated Wasm module directly.
// It measures the internal Rust -> JS storage bridge without adding the public
// SDK's tab -> worker RPC to every sample.
// @ts-ignore Generated by `npm run build:wasm`.
import initWasm, * as wasmBindings from "../dist/wasm/lix_js_sdk.js";

const { benchmarkStorageBridge } = wasmBindings as unknown as {
	benchmarkStorageBridge(
		backend: { roundTrip(payload: unknown): Promise<unknown> },
		calls: number,
		itemsPerCall: number,
		valueBytes: number,
	): Promise<number>;
};

type BenchmarkCase = {
	name: string;
	calls: number;
	itemsPerCall: number;
	valueBytes: number;
};

type BenchmarkResult = BenchmarkCase & {
	samples: number[];
	checksum: number;
};

const backend = {
	roundTrip(payload: unknown): Promise<unknown> {
		return Promise.resolve(payload);
	},
};

self.onmessage = async (event: MessageEvent<{ cases: BenchmarkCase[] }>) => {
	try {
		await initWasm();
		const results: BenchmarkResult[] = [];
		for (const benchmarkCase of event.data.cases) {
			// Warm serde paths and the Promise bridge before recording samples.
			await benchmarkStorageBridge(
				backend,
				benchmarkCase.calls,
				benchmarkCase.itemsPerCall,
				benchmarkCase.valueBytes,
			);
			const samples: number[] = [];
			let checksum = 0;
			for (let sample = 0; sample < 30; sample += 1) {
				const started = performance.now();
				checksum ^= await benchmarkStorageBridge(
					backend,
					benchmarkCase.calls,
					benchmarkCase.itemsPerCall,
					benchmarkCase.valueBytes,
				);
				samples.push(performance.now() - started);
			}
			results.push({ ...benchmarkCase, samples, checksum });
		}
		self.postMessage({ ok: true, results });
	} catch (error) {
		self.postMessage({
			ok: false,
			error: error instanceof Error ? error.stack ?? error.message : String(error),
		});
	}
};
